package data_structures.heaps;
import java.util.*;
import java.util.function.*;
import java.math.*;

public class BinaryHeap {
public static class Heap<T> implements Iterable<T>{private final List<T> items=new ArrayList<>();private final Comparator<T> compare;public Heap(){this(shared.Compare::defaultCompare,List.of());}public Heap(Comparator<T> c){this(c,List.of());}public Heap(Comparator<T> c,Iterable<T> values){compare=c;for(T v:values)items.add(v);for(int i=items.size()/2-1;i>=0;i--)siftDown(i);}public int size(){return items.size();}public boolean isEmpty(){return items.isEmpty();}public T peek(){return isEmpty()?null:items.get(0);}@SafeVarargs public final Heap<T> push(T... values){for(T v:values){items.add(v);siftUp(items.size()-1);}return this;}public T pop(){if(isEmpty())return null;T top=items.get(0),last=items.remove(items.size()-1);if(!isEmpty()){items.set(0,last);siftDown(0);}return top;}public T pushPop(T v){if(isEmpty()||compare.compare(v,items.get(0))<=0)return v;T top=items.set(0,v);siftDown(0);return top;}public List<T> toSortedArray(){Heap<T> copy=new Heap<>(compare,items);List<T> o=new ArrayList<>();while(!copy.isEmpty())o.add(copy.pop());return o;}public Iterator<T> iterator(){return new ArrayList<>(items).iterator();}private void siftUp(int i){while(i>0){int p=(i-1)/2;if(compare.compare(items.get(i),items.get(p))>=0)break;Collections.swap(items,i,p);i=p;}}private void siftDown(int i){while(true){int l=i*2+1,b=i;if(l<items.size()&&compare.compare(items.get(l),items.get(b))<0)b=l;if(l+1<items.size()&&compare.compare(items.get(l+1),items.get(b))<0)b=l+1;if(b==i)return;Collections.swap(items,i,b);i=b;}}}public static class MinHeap<T> extends Heap<T>{public MinHeap(){this(List.of());}public MinHeap(Iterable<T> values){super(shared.Compare::defaultCompare,values);}}public static class MaxHeap<T> extends Heap<T>{public MaxHeap(){this(List.of());}public MaxHeap(Iterable<T> values){super((a,b)->shared.Compare.defaultCompare(b,a),values);}}
}
